module benchmark/solution

import std/io (println)
import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/option (Some, None)

pure func sumLines(lines: [string]) -> int =
  match lines {
    [] => 0,
    line :: rest => {
      let t = trim(line);
      if t == "" then sumLines(rest)
      else match stringToInt(t) {
        Some(n) => n + sumLines(rest),
        None => sumLines(rest)
      }
    }
  }

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let total = sumLines(split(content, "\n"));
      println(show(total))
    },
    _ => println("Usage: program <filename>")
  }
}

module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (Json, encode, jo, ja, kv, js, jnum, decode, getString, getInt, getArray, asString)
import std/result (Result, Ok, Err)
import std/option (Option, Some, None)
import std/string (chars, split, length as strLength)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func countDotsInChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == "." then 1 else 0) + countDotsInChars(rest)
  }

pure func countDots(s: string) -> int = countDotsInChars(chars(s))

pure func isNonEmpty(s: string) -> bool = strLength(s) > 0

pure func isValidPort(port: int) -> bool = port >= 1024 && port <= 65535

pure func isValidVersion(version: string) -> bool {
  let parts = split(version, ".");
  match parts {
    a :: b :: c :: [] => countDots(version) == 2 && isNonEmpty(a) && isNonEmpty(b) && isNonEmpty(c),
    _ => false
  }
}

pure func hasFeatures(features: [string]) -> bool =
  match features {
    [] => false,
    _ => true
  }

pure func countFeatures(features: [string]) -> int =
  match features {
    [] => 0,
    _ :: rest => 1 + countFeatures(rest)
  }

pure func jsonArrayToStrings(items: [Json]) -> Option[[string]] =
  match items {
    [] => Some([]),
    item :: rest => match asString(item) {
      Some(s) => match jsonArrayToStrings(rest) {
        Some(ss) => Some(s :: ss),
        None => None
      },
      None => None
    }
  }

pure func validateConfig(cfg: Config) -> Result[Config, string] =
  if not isValidPort(cfg.port) then Err("Invalid port")
  else if not isValidVersion(cfg.version) then Err("Invalid version")
  else if not hasFeatures(cfg.features) then Err("Features list must not be empty")
  else Ok(cfg)

func createConfigFile(path: string) -> () ! {FS} {
  let content = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));
  writeFile(path, content)
}

func loadConfig(path: string) -> Result[Config, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(obj) => match getString(obj, "app_name") {
      Some(appName) => match getString(obj, "version") {
        Some(version) => match getInt(obj, "port") {
          Some(port) => match getArray(obj, "features") {
            Some(rawFeatures) => match jsonArrayToStrings(rawFeatures) {
              Some(features) => validateConfig({
                app_name: appName,
                version: version,
                port: port,
                features: features
              }),
              None => Err("Features must be strings")
            },
            None => Err("Missing features")
          },
          None => Err("Missing port")
        },
        None => Err("Missing version")
      },
      None => Err("Missing app_name")
    },
    Err(msg) => Err("Invalid JSON: ${msg}")
  }
}

export func main() -> () ! {IO, FS} {
  createConfigFile("app_config.json");
  match loadConfig("app_config.json") {
    Ok(cfg) => println("Loaded ${cfg.app_name} v${cfg.version} on port ${cfg.port} with ${countFeatures(cfg.features)} features"),
    Err(msg) => println("Error: ${msg}")
  }
}

