import json
import pathlib


def create_config(path: pathlib.Path) -> None:
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"],
    }
    path.write_text(json.dumps(config))


def load_and_validate(path: pathlib.Path) -> dict:
    config = json.loads(path.read_text())

    port = config["port"]
    if not (1024 <= port <= 65535):
        raise ValueError(f"Port {port} out of valid range [1024, 65535]")

    version = config["version"]
    if version.count(".") != 2:
        raise ValueError(f"Version '{version}' must be in X.Y.Z format")

    features = config["features"]
    if not features:
        raise ValueError("Features list must not be empty")

    return config


def main() -> None:
    config_path = pathlib.Path("app_config.json")
    create_config(config_path)
    config = load_and_validate(config_path)
    print(
        f"Loaded {config['app_name']} v{config['version']} "
        f"on port {config['port']} with {len(config['features'])} features"
    )


if __name__ == "__main__":
    main()

