module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export func size(t: Tree) -> int =
  match t {
    Leaf => 0,
    Node(l, _, r) => 1 + size(l) + size(r)
  }

export func contains(t: Tree, x: int) -> bool =
  match t {
    Leaf => false,
    Node(l, v, r) =>
      if x == v then true
      else if x < v then contains(l, x)
      else contains(r, x)
  }

export func insert(t: Tree, x: int) -> Tree =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(l, v, r) =>
      if x == v then t
      else if x < v then Node(insert(l, x), v, r)
      else Node(l, v, insert(r, x))
  }

export func isBST(t: Tree, min: int, max: int) -> bool =
  match t {
    Leaf => true,
    Node(l, v, r) =>
      v > min && v < max &&
      isBST(l, min, v) &&
      isBST(r, v, max)
  }

export func insertPreservesBST(x: int) -> bool =
  isBST(insert(Leaf, x), -999999, 999999)

export func insertThenFind(x: int) -> bool =
  contains(insert(Leaf, x), x)

export func main() -> () ! {IO} {
  let t0 = Leaf;
  let t1 = insert(t0, 5);
  let t2 = insert(t1, 3);
  let t3 = insert(t2, 7);
  println(show(size(t3)));
  println(show(contains(t3, 3)));
  println(show(contains(t3, 4)));
  println(show(isBST(t3, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

