from __future__ import annotations
from dataclasses import dataclass
from typing import Optional


@dataclass
class Node:
    value: int
    left: "BST"
    right: "BST"


BST = Optional[Node]
Leaf: BST = None


def insert(tree: BST, value: int) -> BST:
    if tree is None:
        return Node(value, None, None)
    if value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    elif value > tree.value:
        return Node(tree.value, tree.left, insert(tree.right, value))
    else:
        return tree  # no duplicates


def contains(tree: BST, value: int) -> bool:
    if tree is None:
        return False
    if value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    else:
        return contains(tree.right, value)


def size(tree: BST) -> int:
    if tree is None:
        return 0
    return 1 + size(tree.left) + size(tree.right)


def isBST(tree: BST, lo: int, hi: int) -> bool:
    if tree is None:
        return True
    if tree.value <= lo or tree.value >= hi:
        return False
    return isBST(tree.left, lo, tree.value) and isBST(tree.right, tree.value, hi)


def insertPreservesBST(value: int) -> bool:
    """Proof: inserting into a valid BST produces a valid BST."""
    tree = Leaf
    tree = insert(tree, value)
    return isBST(tree, -999999, 999999)


def insertThenFind(value: int) -> bool:
    """Proof: after inserting a value, it can be found."""
    tree = insert(Leaf, value)
    return contains(tree, value)


def main() -> None:
    t = insert(insert(insert(Leaf, 5), 3), 7)
    print(size(t))
    print("true" if contains(t, 3) else "false")
    print("true" if contains(t, 4) else "false")
    print("true" if isBST(t, -999999, 999999) else "false")
    print("true" if insertPreservesBST(42) else "false")
    print("true" if insertThenFind(42) else "false")


if __name__ == "__main__":
    main()

