import re

def encode(s: str) -> str:
    if not s:
        return ""

    encoded_string_parts = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            encoded_string_parts.append(str(count) + s[i-1])
            count = 1

    encoded_string_parts.append(str(count) + s[-1])
    return "".join(encoded_string_parts)

def decode(s: str) -> str:
    if not s:
        return ""

    decoded_string_parts = []
    # Regex to find count and character pairs.
    # (\d+) captures one or more digits (the count)
    # ([a-zA-Z]) captures a single alphabet character (the character)
    matches = re.findall(r'(\d+)([a-zA-Z])', s)

    for count_str, char in matches:
        count = int(count_str)
        decoded_string_parts.append(char * count)

    return "".join(decoded_string_parts)

def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s

def singleCharEncode(s: str) -> bool:
    # This proof function checks if encoding a single character string `s`
    # results in "1" + s.
    if len(s) != 1:
        # According to the problem description, proof functions must always return true.
        # This implies that `singleCharEncode` will always be called with a single character string.
        return False
    return encode(s) == "1" + s

def main():
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(str(roundtrip("hello")).lower())
    print(str(singleCharEncode("q")).lower())

if __name__ == "__main__":
    main()

