module benchmark/solution

import std/string (startsWith, substring, length)

pure func repeatText(s: string, n: int) -> string =
  if n <= 0 then "" else "${s}${repeatText(s, n - 1)}"

pure func digitRoman(d: int, one: string, five: string, ten: string) -> string =
  match d {
    0 => "",
    1 => one,
    2 => repeatText(one, 2),
    3 => repeatText(one, 3),
    4 => "${one}${five}",
    5 => five,
    6 => "${five}${one}",
    7 => "${five}${repeatText(one, 2)}",
    8 => "${five}${repeatText(one, 3)}",
    _ => "${one}${ten}"
  }

pure func thousandsRoman(d: int) -> string = repeatText("M", d)

pure func restAfter(s: string, n: int) -> string = substring(s, n, length(s))

pure func parseRomanRaw(s: string) -> int =
  if s == "" then 0
  else if startsWith(s, "CM") then 900 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "CD") then 400 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "XC") then 90 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "XL") then 40 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "IX") then 9 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "IV") then 4 + parseRomanRaw(restAfter(s, 2))
  else if startsWith(s, "M") then 1000 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "D") then 500 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "C") then 100 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "L") then 50 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "X") then 10 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "V") then 5 + parseRomanRaw(restAfter(s, 1))
  else if startsWith(s, "I") then 1 + parseRomanRaw(restAfter(s, 1))
  else 0

export func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  let thousands = thousandsRoman(n / 1000);
  let hundreds = digitRoman((n % 1000) / 100, "C", "D", "M");
  let tens = digitRoman((n % 100) / 10, "X", "L", "C");
  let ones = digitRoman(n % 10, "I", "V", "X");
  "${thousands}${hundreds}${tens}${ones}"
}

export func fromRoman(s: string) -> int ! {} {
  parseRomanRaw(s)
}

export func roundtrip(n: int) -> bool ! {}
ensures { result == true }
{
  if n < 1 || n > 3999 then true else fromRoman(toRoman(n)) == n
}

export func distinctEncoding(a: int, b: int) -> bool ! {}
ensures { result == true }
{
  if a < 1 || a > 3999 || b < 1 || b > 3999 then true
  else if a == b then true
  else toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

export type SSet = SNil | SCons(int, SSet)

export func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

export func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => match rest {
      SNil => true,
      SCons(y, _) => x < y && isSorted(rest)
    }
  }

export func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if x > y then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }

export func sIntersect(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if x > y then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }

pure func toStrTail(s: SSet) -> string =
  match s {
    SNil => "}",
    SCons(x, rest) => ", ${show(x)}${toStrTail(rest)}"
  }

export func toStr(s: SSet) -> string =
  match s {
    SNil => "{}",
    SCons(x, rest) => "{${show(x)}${toStrTail(rest)}"
  }

export func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  true

export func inclusionExclusion(a: SSet, b: SSet) -> bool =
  sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

