from __future__ import annotations
from dataclasses import dataclass
from typing import Union


@dataclass
class SNil:
    pass


@dataclass
class SCons:
    head: int
    tail: SortedSet


SortedSet = Union[SNil, SCons]


def sLength(s: SortedSet) -> int:
    match s:
        case SNil():
            return 0
        case SCons(head, tail):
            return 1 + sLength(tail)


def toStr(s: SortedSet) -> str:
    elements = []
    current = s
    while isinstance(current, SCons):
        elements.append(str(current.head))
        current = current.tail
    return "[" + ",".join(elements) + "]"


def isSorted(s: SortedSet) -> bool:
    match s:
        case SNil():
            return True
        case SCons(head, SNil()):
            return True
        case SCons(head, SCons(next_head, _) as tail):
            return head < next_head and isSorted(tail)


def sMerge(a: SortedSet, b: SortedSet) -> SortedSet:
    match (a, b):
        case (SNil(), _):
            return b
        case (_, SNil()):
            return a
        case (SCons(ah, at), SCons(bh, bt)):
            if ah < bh:
                return SCons(ah, sMerge(at, b))
            elif bh < ah:
                return SCons(bh, sMerge(a, bt))
            else:  # equal, deduplicate
                return SCons(ah, sMerge(at, bt))


def sIntersect(a: SortedSet, b: SortedSet) -> SortedSet:
    match (a, b):
        case (SNil(), _) | (_, SNil()):
            return SNil()
        case (SCons(ah, at), SCons(bh, bt)):
            if ah == bh:
                return SCons(ah, sIntersect(at, bt))
            elif ah < bh:
                return sIntersect(at, b)
            else:
                return sIntersect(a, bt)


def mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool:
    return isSorted(sMerge(a, b))


def inclusionExclusion(a: SortedSet, b: SortedSet) -> bool:
    return sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)


def main() -> None:
