pure func parseFields(fields: [string]) -> Option[User] =
  match fields {
    name :: rest1 => match rest1 {
      ageStr :: rest2 => match rest2 {
        email :: rest3 => match rest3 {
          [] => match stringToInt(trim(ageStr)) {
            Some(age) =>
              if age > 0 && contains(trim(email), "@") then
                Some({name: trim(name), age: age, email: trim(email)})
              else
                None,
            None => None
          },
          _ => None
        },
        _ => None
      },
      _ => None
    },
    _ => None
  }

