pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func neighborsOf(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    (n, ns) :: rest => if node == n then ns else neighborsOf(node, rest)
  }

pure func enqueueNeighbors(neighbors: [int], queue: [int], visited: [int]) -> [int] =
  match neighbors {
    [] => queue,
    n :: rest =>
      if contains(n, visited) || contains(n, queue)
      then enqueueNeighbors(rest, queue, visited)
      else enqueueNeighbors(rest, enqueue(n, queue), visited)
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int], order: [int]) -> [int] =
  match queue {
    [] => order,
    node :: rest =>
      if contains(node, visited) then bfsLoop(graph, rest, visited, order)
      else
        let nextVisited = enqueue(node, visited) in
        let nextOrder = enqueue(node, order) in
        let nextQueue = enqueueNeighbors(neighborsOf(node, graph), rest, nextVisited) in
        bfsLoop(graph, nextQueue, nextVisited, nextOrder)
  }

pure func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [], [])

