import std/fs (writeFile, readFile)
import std/io (println)
import std/string (split, join, startsWith, trim, compare)
import std/list (length as listLength)
import std/option (Option, Some, None)

type Parsed = {level: string, message: string}
type Stats = {info: int, error: int, warning: int, users: [string]}

pure func logContent() -> string =
  join("\n", [
    "2024-10-29 10:00:00 INFO User logged in: alice",
    "2024-10-29 10:01:15 ERROR Database connection failed",
    "2024-10-29 10:02:30 INFO User logged in: bob",
    "2024-10-29 10:03:45 WARNING High memory usage: 85%",
    "2024-10-29 10:05:00 ERROR API timeout: /users endpoint",
    "2024-10-29 10:06:15 INFO User logged out: alice"
  ])

pure func parseLine(line: string) -> Parsed =
  match split(line, " ") {
    _ :: _ :: level :: rest => {level: level, message: join(" ", rest)},
    _ => {level: "", message: ""}
  }

pure func extractUser(message: string) -> Option[string] =
  if startsWith(message, "User logged in: ") || startsWith(message, "User logged out: ")
  then match split(message, ": ") {
    _ :: name :: _ => Some(trim(name)),
    _ => None
  }
  else None

pure func insertSortedUnique(user: string, users: [string]) -> [string] =
  match users {
    [] => [user],
    u :: rest =>
      if user == u then users
      else if compare(user, u) < 0 then user :: users
      else u :: insertSortedUnique(user, rest)
  }

pure func addLevel(level: string, stats: Stats) -> Stats =
  if level == "INFO" then {stats | info: stats.info + 1}
  else if level == "ERROR" then {stats | error: stats.error + 1}
  else if level == "WARNING" then {stats | warning: stats.warning + 1}
  else stats

pure func analyze(lines: [string], stats: Stats) -> Stats =
  match lines {
    [] => stats,
    line :: rest => {
      let parsed = parseLine(line);
      let updated = addLevel(parsed.level, stats);
      let updatedWithUser = match extractUser(parsed.message) {
        Some(user) => {updated | users: insertSortedUnique(user, updated.users)},
        None => updated
      };
      analyze(rest, updatedWithUser)
    }
  }

pure func percent(count: int, total: int) -> int =
  if total == 0 then 0 else (count * 100) / total

export func main() -> () ! {IO, FS} {
  let content = logContent();
  writeFile("app.log", content);
  let fileContent = readFile("app.log");
  let lines = split(fileContent, "\n");
  let total = listLength(lines);
  let stats = analyze(lines, {info: 0, error: 0, warning: 0, users: []});
  let usersText = join(", ", stats.users);
  println("Total log entries: ${show(total)}");
  println("INFO: ${show(stats.info)} (${show(percent(stats.info, total))}%)");
  println("ERROR: ${show(stats.error)} (${show(percent(stats.error, total))}%)");
  println("WARNING: ${show(stats.warning)} (${show(percent(stats.warning, total))}%)");
  println("Unique users: ${usersText}")
}

