from dataclasses import dataclass
from typing import Union

# 1. Define an AST
@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    var_name: str
    binding_expr: 'Expr'
    body_expr: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]
Environment = list[tuple[str, int]]

# 3. Implement lookup(name, env)
def lookup(name: str, env: Environment) -> int:
    """Finds a variable's value in the environment."""
    for var_name, value in env:
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found in environment")

# 4. Implement eval(expr, env)
def eval_expr(expr: Expr, env: Environment) -> int:
    """Evaluates an expression in an environment."""
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval_expr(left, env) + eval_expr(right, env)
        case Mul(left, right):
            return eval_expr(left, env) * eval_expr(right, env)
        case Let(var_name, binding_expr, body_expr):
            binding_value = eval_expr(binding_expr, env)
            new_env = [(var_name, binding_value)] + env
            return eval_expr(body_expr, new_env)
        case _:
            raise TypeError(f"Unknown expression type: {type(expr)}")

def main():
    """
    Main function to evaluate the sample program and print the result.
    """
    # 5. Evaluate this program:
