def run_length_encode(input_list: list[str]) -> list[tuple[int, str]]:
    if not input_list:
        return []

    encoded_list: list[tuple[int, str]] = []
    count: int = 0
    current_char: str = ''

    for char in input_list:
        if char == current_char:
            count += 1
        else:
            if count > 0:
                encoded_list.append((count, current_char))
            current_char = char
            count = 1

    # Add the last sequence
    if count > 0:
        encoded_list.append((count, current_char))

