from __future__ import annotations
from dataclasses import dataclass
from typing import Generic, TypeVar

# --- Data Types (ADTs) ---

# State
class State:
    """Base class for all states in the vending machine."""
    pass

@dataclass
class Idle(State):
    """The machine is idle, with no credit."""
    pass

@dataclass
class HasCredit(State):
    """The machine has credit and is waiting for a selection."""
    cents: int

@dataclass
class Dispensing(State):
    """The machine is dispensing an item and has change to return."""
    change: int

# Event
class Event:
    """Base class for all events that can be sent to the state machine."""
    pass

@dataclass
class Insert(Event):
    """Event for inserting coins."""
    cents: int

@dataclass
class Select(Event):
    """Event for selecting an item."""
    code: int

@dataclass
class DispenseDone(Event):
    """Event indicating the item has been dispensed."""
    pass

# Result
T = TypeVar('T')
E = TypeVar('E')

class Result(Generic[T, E]):
    """A generic Result type for returning either a value or an error."""
    pass

@dataclass
class Ok(Result[T, E]):
    """Represents a successful result."""
    value: T

@dataclass
class Err(Result[T, E]):
    """Represents an error result."""
    error: E

# --- Vending Machine Logic ---

PRICES = {1: 125, 2: 75, 3: 100}

def step(state: State, event: Event) -> Result[State, str]:
    """
    Performs a single state transition based on the current state and an event.
    """
    match (state, event):
        case (Idle(), Insert(n)):
            return Ok(HasCredit(n))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        case (HasCredit(c), Insert(n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(c), Select(code)):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            else:
                return Ok(Dispensing(c - price))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(_), DispenseDone()):
            return Ok(Idle())

        # This wildcard case should ideally not be reached in this simulation
        case _:
            return Err("unhandled_state_event_combination")

def print_result(result: Result[State, str]):
    """Prints the result of a step in the required format."""
    match result:
        case Ok(value):
            match value:
                case Idle():
                    print("ok: IDLE")
                case HasCredit(cents):
                    print(f"ok: CREDIT({cents})")
                case Dispensing(change):
                    print(f"ok: DISPENSING({change})")
        case Err(error):
            print(f"err: {error}")

# --- Simulation ---

def main():
    """Runs the vending machine simulation."""
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    current_state: State = Idle()

    for event in events:
        result = step(current_state, event)
        print_result(result)
        if isinstance(result, Ok):
            current_state = result.value

if __name__ == "__main__":
    main()

