type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func double(x: int) -> int = x * 2

pure func add(acc: int, x: int) -> int = acc + x

pure func mapTree(f: int -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(v) => Leaf(f(v)),
    Node(left, v, right) => Node(mapTree(f, left), f(v), mapTree(f, right))
  }

pure func foldTree(f: (int, int) -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => f(acc, v),
    Node(left, v, right) => {
      let acc1 = foldTree(f, acc, left);
      let acc2 = f(acc1, v);
      foldTree(f, acc2, right)
    }
  }
}

pure func treeToList(tree: Tree) -> [int] =
