from dataclasses import dataclass
from typing import Union, List, Callable, TypeVar

# 1. Define a Tree type with two variants
@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

A = TypeVar('A')

# 2. Implement mapTree(fn, tree)
def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    # It's a Node, recursively map children
    return Node(
        mapTree(fn, tree.left),
        fn(tree.value),
        mapTree(fn, tree.right)
    )

# 3. Implement foldTree(fn, acc, tree)
def foldTree(fn: Callable[[A, int], A], acc: A, tree: Tree) -> A:
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    # In-order fold: left, current, right
    acc = foldTree(fn, acc, tree.left)
    acc = fn(acc, tree.value)
    acc = foldTree(fn, acc, tree.right)
    return acc

# 4. Implement treeToList(tree)
def treeToList(tree: Tree) -> List[int]:
    if isinstance(tree, Leaf):
        return [tree.value]
    # In-order traversal to produce the list
    return treeToList(tree.left) + [tree.value] + treeToList(tree.right)

# 5. Implement treeDepth(tree)
def treeDepth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    # Depth is 1 + max depth of subtrees
    return 1 + max(treeDepth(tree.left), treeDepth(tree.right))

# Helper functions for testing
def double(x: int) -> int:
    return x * 2

def add(x: int, y: int) -> int:
    return x + y

def main():
    # 6. Test with the specified tree structure
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # 7. Print the required results

    # - treeToList(tree): [1, 2, 3, 4, 5, 6, 7]
    print(treeToList(tree))

    # - treeToList(mapTree(double, tree)): [2, 4, 6, 8, 10, 12, 14]
    mapped_tree = mapTree(double, tree)
    print(treeToList(mapped_tree))

    # - foldTree(add, 0, tree): 28
    total_sum = foldTree(add, 0, tree)
    print(total_sum)

    # - treeDepth(tree): 3
    depth = treeDepth(tree)
    print(depth)

if __name__ == "__main__":
    main()

