module benchmark/solution

import std/io (println)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type Subst = SNil | SCons(string, Type, Subst)

type UResult = UOk(Subst) | UFail

export func showType(t: Type) -> string =
  match t {
    TVar(n) => "TVar(${n})",
    TInt => "TInt",
    TBool => "TBool",
    TFunc(a, r) => "TFunc(${showType(a)}, ${showType(r)})"
  }

export func apply(s: Subst, t: Type) -> Type =
  match t {
    TVar(n) => lookupApply(s, n, t),
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(apply(s, a), apply(s, r))
  }

export func lookupApply(s: Subst, n: string, orig: Type) -> Type =
  match s {
    SNil => orig,
    SCons(k, v, rest) => if k == n then v else lookupApply(rest, n, orig)
  }

export func appendSubst(s1: Subst, s2: Subst) -> Subst =
  match s1 {
    SNil => s2,
    SCons(k, v, rest) => SCons(k, v, appendSubst(rest, s2))
  }

export func unify(t1: Type, t2: Type) -> UResult =
  match t1 {
    TInt => match t2 {
      TInt => UOk(SNil),
      TVar(b) => UOk(SCons(b, TInt, SNil)),
      _ => UFail
    },
    TBool => match t2 {
      TBool => UOk(SNil),
      TVar(b) => UOk(SCons(b, TBool, SNil)),
      _ => UFail
    },
    TVar(a) => UOk(SCons(a, t2, SNil)),
    TFunc(a1, r1) => match t2 {
      TVar(b) => UOk(SCons(b, t1, SNil)),
      TFunc(a2, r2) => match unify(a1, a2) {
        UFail => UFail,
        UOk(s1) => match unify(apply(s1, r1), apply(s1, r2)) {
          UFail => UFail,
          UOk(s2) => UOk(appendSubst(s1, s2))
        }
      },
      _ => UFail
    }
  }

export func printSubst(s: Subst) -> () ! {IO} =
  match s {
    SNil => (),
    SCons(k, v, rest) => {
      println("${k} = ${showType(v)}");
      printSubst(rest)
    }
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    UFail => println("unification failed"),
    UOk(s) => printSubst(s)
  }
}

