from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class TVar:
    name: str


@dataclass(frozen=True)
class TInt:
    pass


@dataclass(frozen=True)
class TBool:
    pass


@dataclass(frozen=True)
class TFunc:
    arg: "Type"
    result: "Type"


Type = Union[TVar, TInt, TBool, TFunc]

Subst = list[tuple[str, Type]]


def apply(subst: Subst, t: Type) -> Type:
    match t:
        case TVar(name):
            for var, typ in subst:
                if var == name:
                    return apply(subst, typ)
            return t
        case TInt() | TBool():
            return t
        case TFunc(arg, result):
            return TFunc(apply(subst, arg), apply(subst, result))


def compose(s1: Subst, s2: Subst) -> Subst:
    result = [(var, apply(s1, typ)) for var, typ in s2]
    result += [(var, typ) for var, typ in s1 if var not in {v for v, _ in s2}]
    return result


def unify(t1: Type, t2: Type) -> Subst:
    match (t1, t2):
        case (TInt(), TInt()):
            return []
        case (TBool(), TBool()):
            return []
        case (TVar(a), t):
            return [(a, t)]
        case (t, TVar(a)):
            return [(a, t)]
        case (TFunc(a1, r1), TFunc(a2, r2)):
            s1 = unify(a1, a2)
            s2 = unify(apply(s1, r1), apply(s1, r2))
            return compose(s2, s1)
        case _:
            raise TypeError(f"Cannot unify {t1} and {t2}")


def type_to_str(t: Type) -> str:
    match t:
        case TInt():
            return "TInt"
        case TBool():
            return "TBool"
        case TVar(name):
            return f"TVar({name})"
        case TFunc(arg, result):
            return f"TFunc({type_to_str(arg)}, {type_to_str(result)})"


def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    subst = unify(t1, t2)
    for var, typ in subst:
        print(f"{var} = {type_to_str(typ)}")


if __name__ == "__main__":
    main()
